//请勿修改版本号
const localVersion = "5.67";

function login(flag) {
    const host = getServerHost();

    if (flag == undefined) {
        const loginInfo = source.getLoginInfoMap();
        var email = loginInfo['邮箱'];
        var password = loginInfo['密码'];
    } else {
        source.putLoginInfo(JSON.stringify(result));
        var email = result['邮箱'];
        var password = result['密码'];
    }

    if (email) email = String(email).replace(/\s+/g, '').trim();
    if (password) password = String(password).replace(/\s+/g, '').trim();

    if (!email || !password) {
        java.toast("\n❌ 请先填写账号和密码并点击✓保存后登录");
        return;
    }

    java.toast("正在登录...");
    const url = host + '/login';
    const body = "email=" + encodeURIComponent(email) + "&password=" + encodeURIComponent(password);

    try {
        const response = java.ajax(url + "," + JSON.stringify({
            method: "POST",
            body: body,
            timeout: 10000
        }));

        const data = JSON.parse(response);

        if (data.code == 200) {
            const user = data.data.user;
            const deviceInfo = data.data.device || {};

            source.putLoginHeader(user.api_key);

            const nickname = user.nickname || "用户";
            const maskedEmail = email.includes('@') ? 
                email.substring(0, 3) + "****" + email.substring(email.indexOf('@')) : 
                email;
            const memberStatus = (user.is_member || false) ? "会员用户" : "普通用户";
            const welcomeMsg = (user.is_member || false) ? "欢迎回来，尊贵的会员" : "欢迎回来";

            const onlineCount = deviceInfo.online_count || 0;
            const deviceLimit = deviceInfo.device_limit || 1;
            const totalCount = deviceInfo.total_count || 0;

            var deviceStatusText = "";
            if (onlineCount >= deviceLimit && totalCount > 0) {
                deviceStatusText = "⚠️ 设备已满（" + onlineCount + "/" + deviceLimit + "）\n新设备登录将挤掉旧设备";
            } else if (onlineCount > 0) {
                deviceStatusText = "📱 在线设备：" + onlineCount + "/" + deviceLimit;
            } else {
                deviceStatusText = "📱 当前无其他设备在线";
            }

            function maskDeviceId(deviceId) {
                if (!deviceId || deviceId.length <= 8) return deviceId || '未知';
                return deviceId.substring(0, 4) + "****" + deviceId.substring(deviceId.length - 4);
            }

            function maskIp(ip) {
                if (!ip) return '';
                if (ip.indexOf('.') !== -1 && ip.indexOf(':') == -1) {
                    var parts = ip.split('.');
                    if (parts.length == 4) return parts[0] + '.' + parts[1] + '.*.*';
                }
                if (ip.indexOf(':') !== -1) {
                    var parts = ip.split(':');
                    var validParts = [];
                    for (var i = 0; i < parts.length; i++) {
                        if (parts[i] !== '') validParts.push(parts[i]);
                    }
                    if (validParts.length >= 4) return validParts.slice(0, 4).join(':') + ':*:*';
                }
                return ip;
            }

            var deviceListText = "";
            var deviceList = (deviceInfo && deviceInfo.list) ? deviceInfo.list : [];
            if (deviceList && deviceList.length > 0) {
                deviceListText = "\n── 设备列表 ──";
                for (var i = 0; i < deviceList.length; i++) {
                    var dev = deviceList[i];
                    var statusIcon = dev.is_online ? '🟢' : '⚫';
                    var maskedId = maskDeviceId(dev.device_id);
                    var maskedIp = maskIp(dev.ip_address);
                    var ipText = maskedIp ? ' | ' + maskedIp : '';
                    deviceListText += "\n" + statusIcon + " " + maskedId + ipText;
                }
            }

            java.toast(
                "\n───────────────\n" +
                "🌟 " + welcomeMsg + " 🌟\n" +
                "───────────────\n" +
                "昵称：" + nickname + "\n" +
                "邮箱：" + maskedEmail + "\n" +
                "状态：" + memberStatus + "\n" +
                "───────────────\n" +
                deviceStatusText +
                deviceListText + "\n" +
                "───────────────"
            );
        } else {
            java.toast(
                "\n───────────────\n" +
                "❌ 登录失败 ❌\n" +
                "───────────────\n" +
                "错误代码：" + (data.code || "未知") + "\n" +
                "错误信息：" + (data.message || "未知错误") + "\n" +
                "───────────────"
            );
        }

    } catch (e) {
        java.toast(
            "\n───────────────\n" +
            "❌ 网络错误 ❌\n" +
            "───────────────\n" +
            "连接服务器失败\n" +
            "请检查网络连接\n" +
            "请切换服务器尝试\n" +
            "───────────────"
        );
    }
}

function user_logout() {
    let hadLogin = false;

    if (source.getLoginHeader() && String(source.getLoginHeader()).trim().length > 0) {
        hadLogin = true;
    }

    try {
        var apiUrl = getServerHost() + '/api/logout';
        var response = java.ajax(apiUrl + "," + JSON.stringify({
            method: "POST",
            headers: {
                "Content-Type": "application/json"
            },
            timeout: 5000
        }));
    } catch (e) {}

    try {
        cookie.removeCookie(getServerHost());
    } catch (e) {}

    source.putLoginHeader("");

    if (!source.getLoginHeader() || String(source.getLoginHeader()).trim().length == 0) {
        java.toast(hadLogin ? "\n❗ 已成功退出登录" : "\nℹ️ 当前未登录状态");
    }
}

function hasValidCustomSource() {
    return false;
}

function updateConfig(key, value, message, gender) {
    if (gender !== undefined) {
        setConfigs.call(this, {[key]: value, gender: gender});
    } else {
        setConfig.call(this, key, value);
    }
    java.toast(message || "设置已更新");
}

function get_user() {
    try {
        var apiKey = getSecretKey();
        if (!apiKey) {
            java.toast("❌ 未获取到密钥，请先登录");
            return;
        }

        var timestamp = Math.floor(Date.now() / 1000);
        var apiUrl = getServerHost() + '/login';

        var postData = {
            key: apiKey,
            timestamp: timestamp
        };

        var response = java.ajax(apiUrl + "," + JSON.stringify({
            method: "POST",
            body: JSON.stringify(postData),
            headers: {
                "Content-Type": "application/json"
            },
            timeout: 10000
        }));

        var data = JSON.parse(response);

        if (data.data.user) {
            var userInfo = data.data.user;
            var deviceInfo = data.data.device || {};

            var statusDisplay = "";
            switch(userInfo.status) {
                case "正常":
                    statusDisplay = "✅ 正常";
                    break;
                case "会员":
                    statusDisplay = "👑VIP会员";
                    break;
                case "封禁":
                    statusDisplay = "🚫 封禁";
                    break;
                default:
                    statusDisplay = userInfo.status || "正常";
            }

            var email = userInfo.email || "未绑定";
            var maskedEmail = "未绑定";
            if (email !== "未绑定" && email.includes("@")) {
                var parts = email.split("@");
                var username = parts[0];
                var domain = parts[1];
                if (username.length > 2) {
                    maskedEmail = username.substring(0, 2) + "****@" + domain;
                } else {
                    maskedEmail = username + "****@" + domain;
                }
            }

            var nickname = userInfo.nickname || "未设置";
            if (nickname == "未设置") {
                nickname = "👤 " + nickname;
            } else {
                nickname = "👤 " + nickname;
            }

            // 设备信息处理
            var onlineCount = deviceInfo.online_count || 0;
            var deviceLimit = deviceInfo.device_limit || 1;
            var totalCount = deviceInfo.total_count || 0;

            var deviceStatusText = "";
            if (onlineCount >= deviceLimit && totalCount > 0) {
                deviceStatusText = "⚠️ 设备已满（" + onlineCount + "/" + deviceLimit + "）";
            } else if (onlineCount > 0) {
                deviceStatusText = "📱 在线设备：" + onlineCount + "/" + deviceLimit;
            } else {
                deviceStatusText = "📱 当前无设备在线";
            }

            function maskDeviceId(deviceId) {
                if (!deviceId || deviceId.length <= 8) return deviceId || '未知';
                return deviceId.substring(0, 4) + "****" + deviceId.substring(deviceId.length - 4);
            }

            function maskIp(ip) {
                if (!ip) return '';
                if (ip.indexOf('.') !== -1 && ip.indexOf(':') == -1) {
                    var parts = ip.split('.');
                    if (parts.length == 4) return parts[0] + '.' + parts[1] + '.*.*';
                }
                if (ip.indexOf(':') !== -1) {
                    var parts = ip.split(':');
                    var validParts = [];
                    for (var i = 0; i < parts.length; i++) {
                        if (parts[i] !== '') validParts.push(parts[i]);
                    }
                    if (validParts.length >= 4) return validParts.slice(0, 4).join(':') + ':*:*';
                }
                return ip;
            }

            function formatTime(timeStr) {
                if (!timeStr || timeStr == "从未使用") return "未知";
                return timeStr;
            }

            var deviceListText = "";
            var deviceList = (deviceInfo && deviceInfo.list) ? deviceInfo.list : [];
            if (deviceList && deviceList.length > 0) {
                deviceListText = "\n── 设备列表 ──";
                for (var i = 0; i < deviceList.length; i++) {
                    var dev = deviceList[i];
                    var statusIcon = dev.is_online ? '🟢' : '⚫';
                    var maskedId = maskDeviceId(dev.device_id);
                    var maskedIp = maskIp(dev.ip_address);
                    var deviceName = dev.device_name || '未知设备';
                    var trustedIcon = dev.is_trusted ? ' 🔒' : '';
                    var lastSeen = dev.last_seen || '未知';

                    deviceListText += "\n" + statusIcon + " " + maskedId + trustedIcon;
                    deviceListText += "\n   📱 " + deviceName + " | " + (maskedIp || '未知IP');
                    deviceListText += "\n   ⏰ " + lastSeen;
                    if (i < deviceList.length - 1) {
                        deviceListText += "\n";
                    }
                }
            } else {
                deviceListText = "\n── 设备列表 ──\n暂无设备记录";
            }

            var displayContent = 
                "\n────────────\n" +
                "📊 用 户 信 息 📊\n" +
                "────────────\n" +
                nickname + "\n" +
                "────────────\n" +
                "📧 绑定邮箱\n" + maskedEmail + "\n" +
                "────────────\n" +
                "📊 累计阅读\n" + (userInfo.total_usage || 0) + " 次\n" +
                "────────────\n" +
                "📈 今日阅读\n" + (userInfo.today_usage || 0) + " 次\n" +
                "────────────\n" +
                "🔄 账户状态\n" + statusDisplay + "\n" +
                "────────────\n" +
                "📅 注册时间\n" + (userInfo.created_at || "未知") + "\n" +
                "────────────\n" +
                "🖥️ 设备管理\n" +
                "总数：" + totalCount + " | " + deviceStatusText + "\n" +
                (deviceInfo.current_device_online ? "🟢 当前设备在线\n" : "") +
                (deviceInfo.is_kicked ? "⚠️ 设备已被踢出：" + deviceInfo.kicked_reason + "\n" : "") +
                deviceListText + "\n";

            if (userInfo.is_banned) {
                displayContent += "────────────\n" +
                                "🚫 封禁信息\n" + (userInfo.banned_info || "已封禁") + "\n";
            }

            if (userInfo.last_used && userInfo.last_used !== "从未使用") {
                displayContent += "────────────\n" +
                                "⏰ 最后使用\n" + userInfo.last_used + "\n";
            }

            if (userInfo.is_member) {
                displayContent += "────────────\n" +
                                "💎 会员状态\n👑 尊贵VIP会员\n";
            }

            displayContent += "────────────\n" +
                            "✨ 查询完成";

            java.longToast(displayContent);

        } else {
            var errorMsg = data.message || "未知错误";
            java.longToast("❌ 查询失败：" + errorMsg);
        }

    } catch (e) {
        java.longToast("❌ 网络连接异常，请稍后重试");
    }
}

